{
  "scenarios": [
    {
      "id": "M01-01",
      "category": "工作作息与睡眠时间变化",
      "turns": [
        {
          "user": "我最近因为项目上线，连续三周每天只睡四个小时，早上六点就要到公司开会，晚上经常加班到凌晨两点才回家休息。",
          "assistant": "收到，已记录您近期因项目导致的睡眠减少情况。"
        },
        {
          "user": "补充一下，上周四开始我已经调整回正常作息了，现在能保证每晚七点睡，早上八点起，不再熬夜加班了。",
          "assistant": "明白，已更新您从上周四开始的作息恢复记录。"
        }
      ],
      "queries": [
        {
          "id": "q1",
          "query": "这位用户之前为了赶项目进度，具体保持了多久的短睡眠状态？",
          "expected_facts": [
            "该用户在项目上线期间连续三周每天仅睡四小时。",
            "该用户在此期间早上六点上班，晚上常加班至凌晨两点。"
          ],
          "required_groups": [
            ["连续三周", "整整三周"],
            ["每天只睡四个小时", "每日仅睡四小时"]
          ]
        },
        {
          "id": "q2",
          "query": "用户是从什么时候开始恢复正常睡眠时间的？现在的作息是怎样的？",
          "expected_facts": [
            "该用户从上周四开始调整回正常作息。",
            "该用户目前每晚七点入睡，早上八点起床。"
          ],
          "required_groups": [
            ["上周四", "上星期四"],
            ["每晚七点睡", "晚上七点睡觉"],
            ["早上八点起", "早晨八点起床"]
          ]
        }
      ]
    },
    {
      "id": "M01-02",
      "category": "工作作息与睡眠时间变化",
      "turns": [
        {
          "user": "上个月换班后，我被迫改成夜班，从晚上十点干到早上六点，导致白天完全睡不着，只能眯半小时。",
          "assistant": "好的，已记录您上个月转为夜班后的睡眠困扰。"
        },
        {
          "user": "更正一下，其实我是这个月一号才正式转夜班的，而且昨天刚申请调回白班，今天已经开始尝试早睡早起了。",
          "assistant": "收到，已修正您的夜班起始时间并记录今日调回白班的计划。"
        }
      ],
      "queries": [
        {
          "id": "q1",
          "query": "用户实际是从哪一天开始执行夜班工作的？当时的睡眠状况如何？",
          "expected_facts": [
            "该用户从本月一号正式转为夜班工作。",
            "该用户当时白天无法入睡，仅能小憩半小时。"
          ],
          "required_groups": [
            ["这个月一号", "本月一日"],
            ["白天完全睡不着", "白天无法入睡"],
            ["只能眯半小时", "仅能小憩半小时"]
          ]
        },
        {
          "id": "q2",
          "query": "用户何时决定结束夜班生活？目前的行动是什么？",
          "expected_facts": [
            "该用户于昨天申请调回白班。",
            "该用户今天已开始尝试早睡早起。"
          ],
          "required_groups": [
            ["昨天", "昨日"],
            ["调回白班", "转回白班"],
            ["尝试早睡早起", "开始早睡早起"]
          ]
        }
      ]
    },
    {
      "id": "M01-03",
      "category": "工作作息与睡眠时间变化",
      "turns": [
        {
          "user": "去年年底为了赶年终报告，我连续半个月每天凌晨三点才睡，早上七点就得爬起来去打印资料。",
          "assistant": "了解，已记录您去年年底因赶报告而长期晚睡的情况。"
        },
        {
          "user": "不对，那是前年十二月的事，去年年底我其实已经休假了，并没有那么累，只是偶尔晚睡而已。",
          "assistant": "明白，已将相关事件时间修正为前年十二月。"
        }
      ],
      "queries": [
        {
          "id": "q1",
          "query": "用户提到曾因赶报告而严重缺觉，这件事具体发生在哪一年？持续了多久？",
          "expected_facts": [
            "该事件发生在前年十二月。",
            "该用户当时连续半个月每天凌晨三点才睡。"
          ],
          "required_groups": [
            ["前年十二月", "两年前十二月"],
            ["连续半个月", "整整半个月"],
            ["凌晨三点才睡", "半夜三点入睡"]
          ]
        },
        {
          "id": "q2",
          "query": "关于去年年底的作息，用户后来是如何澄清的？",
          "expected_facts": [
            "该用户去年年底实际上处于休假状态。",
            "该用户去年年底并未严重缺觉，只是偶尔晚睡。"
          ],
          "required_groups": [
            ["去年年底", "去年年末"],
            ["休假了", "在休假"],
            ["偶尔晚睡", "有时睡得晚"]
          ]
        }
      ]
    },
    {
      "id": "M01-04",
      "category": "工作作息与睡眠时间变化",
      "turns": [
        {
          "user": "自从接手新部门，我每周二和周四都要开跨国会议，必须凌晨一点起床准备，导致这两天几乎整夜失眠。",
          "assistant": "收到，已记录您因跨国会议导致的特定日期失眠问题。"
        },
        {
          "user": "补充说明，下个月起会议时间会调整到下午，所以我预计下周开始就能恢复正常夜间睡眠了。",
          "assistant": "好的，已备注您下个月会议时间变更及预期睡眠改善。"
        }
      ],
      "queries": [
        {
          "id": "q1",
          "query": "用户目前哪些天需要凌晨起床？这造成了什么后果？",
          "expected_facts": [
            "该用户每周二和周四需凌晨一点起床准备会议。",
            "该用户在这两天几乎整夜失眠。"
          ],
          "required_groups": [
            ["每周二和周四", "周二周四"],
            ["凌晨一点起床", "一点钟起床"],
            ["几乎整夜失眠", "整晚睡不着"]
          ]
        },
        {
          "id": "q2",
          "query": "用户的会议安排何时会有变动？这对睡眠有何影响？",
          "expected_facts": [
            "该用户的会议时间将于下个月调整为下午。",
            "该用户预计下周起可恢复正常夜间睡眠。"
          ],
          "required_groups": [
            ["下个月", "次月"],
            ["调整为下午", "改到下午"],
            ["恢复正常夜间睡眠", "恢复晚上睡觉"]
          ]
        }
      ]
    },
    {
      "id": "M01-05",
      "category": "工作作息与睡眠时间变化",
      "turns": [
        {
          "user": "三个月前我开始远程办公，结果在家反而更乱了，经常忙到深夜两三点，早上九点才勉强起床。",
          "assistant": "明白，已记录您远程办公初期作息混乱的情况。"
        },
        {
          "user": "其实不是三个月前，是两个月前开始的，而且我现在已经制定了严格时间表，昨晚十一点就睡了。",
          "assistant": "收到，已修正开始时间并记录您昨晚的早睡行为。"
        }
      ],
      "queries": [
        {
          "id": "q1",
          "query": "用户实际是什么时候开始远程办公的？当时的作息有什么特点？",
          "expected_facts": [
            "该用户于两个月前开始远程办公。",
            "该用户当时常忙至深夜两三点，早上九点才起床。"
          ],
          "required_groups": [
            ["两个月前", "两月前"],
            ["深夜两三点", "凌晨两三点"],
            ["早上九点才起床", "九点才醒"]
          ]
        },
        {
          "id": "q2",
          "query": "用户最近采取了什么措施来改善作息？效果如何？",
          "expected_facts": [
            "该用户已制定严格的时间表。",
            "该用户昨晚十一点就已入睡。"
          ],
          "required_groups": [
            ["制定了严格时间表", "有了严格计划"],
            ["昨晚十一点就睡了", "昨夜十一点入睡"]
          ]
        }
      ]
    },
    {
      "id": "M01-06",
      "category": "工作作息与睡眠时间变化",
      "turns": [
        {
          "user": "今年春节假期后，我为了补完积压的工作，连续十天每天只睡五个小时，精神非常疲惫。",
          "assistant": "好的，已记录您春节后补工期间的短期睡眠不足。"
        },
        {
          "user": "更正一下，其实是春节放假期间我就在加班，假期结束后才稍微缓过来，现在每天能睡六小时了。",
          "assistant": "明白，已更新您春节期间的加班情况及当前睡眠时长。"
        }
      ],
      "queries": [
        {
          "id": "q1",
          "query": "用户最初描述的高强度工作期是在什么时候？持续了多久？",
          "expected_facts": [
            "该用户最初称高强度工作期为春节假期后。",
            "该用户当时连续十天每天只睡五个小时。"
          ],
          "required_groups": [
            ["春节假期后", "过年后"],
            ["连续十天", "整整十天"],
            ["每天只睡五个小时", "每日仅睡五小时"]
          ]
        },
        {
          "id": "q2",
          "query": "用户后来对加班时间做了怎样的修正？现在的睡眠状况怎样？",
          "expected_facts": [
            "该用户实际是在春节放假期间就在加班。",
            "该用户现在每天能睡六个小时。"
          ],
          "required_groups": [
            ["春节放假期间", "过年期间"],
            ["每天能睡六小时", "每日睡六小时"]
          ]
        }
      ]
    },
    {
      "id": "M01-07",
      "category": "工作作息与睡眠时间变化",
      "turns": [
        {
          "user": "半年前换了新主管，要求我们全员实行弹性工作制，我因此经常凌晨四点下班，早上十点才回家补觉。",
          "assistant": "收到，已记录您半年前因弹性工作制导致的作息颠倒。"
        },
        {
          "user": "不对，弹性工作制是八个月前实施的，而且上周主管宣布取消该制度，我今晚就能按正常时间下班了。",
          "assistant": "明白，已修正制度实施时间并记录本周取消通知。"
        }
      ],
      "queries": [
        {
          "id": "q1",
          "query": "用户提到的弹性工作制实际是何时开始的？当时导致了什么作息问题？",
          "expected_facts": [
            "该弹性工作制于八个月前实施。",
            "该用户当时经常凌晨四点下班，早上十点回家补觉。"
          ],
          "required_groups": [
            ["八个月前", "八月前"],
            ["凌晨四点下班", "四点下班"],
            ["早上十点回家补觉", "十点回家睡觉"]
          ]
        },
        {
          "id": "q2",
          "query": "该工作制度何时被叫停？用户对此有何反应？",
          "expected_facts": [
            "该制度于上周被主管宣布取消。",
            "该用户今晚即可按正常时间下班。"
          ],
          "required_groups": [
            ["上周", "上个星期"],
            ["取消该制度", "废除该制度"],
            ["按正常时间下班", "正常时间离开"]
          ]
        }
      ]
    },
    {
      "id": "M01-08",
      "category": "工作作息与睡眠时间变化",
      "turns": [
        {
          "user": "上个月参加行业峰会时，我为了赶飞机，连续三天凌晨两点出发，导致那几天完全没怎么睡觉。",
          "assistant": "好的，已记录您上月参会期间的极度疲劳状态。"
        },
        {
          "user": "补充细节，其实是四天而不是三天，而且回程那天我直接睡了十二个小时才缓过来。",
          "assistant": "收到，已修正天数并记录您回程后的长时睡眠。"
        }
      ],
      "queries": [
        {
          "id": "q1",
          "query": "用户参加峰会期间，实际有多少天需要凌晨出发？",
          "expected_facts": [
            "该用户实际有四天需要凌晨两点出发。",
            "该用户在那几天几乎完全没有睡觉。"
          ],
          "required_groups": [
            ["四天", "四个整天"],
            ["凌晨两点出发", "两点动身"],
            ["完全没怎么睡觉", "几乎没睡"]
          ]
        },
        {
          "id": "q2",
          "query": "用户回程当天的睡眠情况如何？",
          "expected_facts": [
            "该用户回程当天直接睡了十二个小时。",
            "该用户通过长睡恢复了体力。"
          ],
          "required_groups": [
            ["回程那天", "返回当天"],
            ["睡了十二个小时", "睡了十二小时"],
            ["缓过来", "恢复体力"]
          ]
        }
      ]
    },
    {
      "id": "M01-09",
      "category": "工作作息与睡眠时间变化",
      "turns": [
        {
          "user": "去年夏天为了完成毕业设计，我连续一个月每天只睡三个小时，靠咖啡硬撑，直到答辩前一天才崩溃。",
          "assistant": "了解，已记录您去年夏季因毕业设计导致的严重睡眠剥夺。"
        },
        {
          "user": "更正一下，那是大三暑假的事，不是去年，而且我答辩后休整了一周，现在作息已经完全正常了。",
          "assistant": "明白，已将时间修正为大三暑假并记录后续恢复情况。"
        }
      ],
      "queries": [
        {
          "id": "q1",
          "query": "用户提到的毕业设计压力期具体发生在哪个时间段？睡眠状况如何？",
          "expected_facts": [
            "该事件发生在大三暑假。",
            "该用户当时连续一个月每天只睡三个小时。"
          ],
          "required_groups": [
            ["大三暑假", "大学三年级暑假"],
            ["连续一个月", "整整一月"],
            ["每天只睡三个小时", "每日仅睡三小时"]
          ]
        },
        {
          "id": "q2",
          "query": "用户答辩后经历了怎样的恢复过程？目前状态如何？",
          "expected_facts": [
            "该用户答辩后休整了一周。",
            "该用户目前作息已完全正常。"
          ],
          "required_groups": [
            ["答辩后", "答辩之后"],
            ["休整了一周", "休息了一周"],
            ["作息完全正常", "生活规律正常"]
          ]
        }
      ]
    },
    {
      "id": "M01-10",
      "category": "工作作息与睡眠时间变化",
      "turns": [
        {
          "user": "两周前开始轮岗，我被分到急诊科，连续七天每天工作十四小时，只能在休息室眯二十分钟。",
          "assistant": "收到，已记录您两周前轮岗急诊科的超负荷工作状态。"
        },
        {
          "user": "补充一下，其实是九天而不是七天，而且今天轮岗结束，我已经回家睡了个安稳觉。",
          "assistant": "明白，已修正轮岗天数并记录您今日的休息情况。"
        }
      ],
      "queries": [
        {
          "id": "q1",
          "query": "用户轮岗急诊科的实际时长是多少？期间睡眠如何？",
          "expected_facts": [
            "该用户实际轮岗了九天。",
            "该用户期间每天工作十四小时，仅能休息二十分钟。"
          ],
          "required_groups": [
            ["九天", "九个整天"],
            ["每天工作十四小时", "日工作十四小时"],
            ["眯二十分钟", "休息二十分钟"]
          ]
        },
        {
          "id": "q2",
          "query": "用户何时结束轮岗？之后的睡眠情况怎样？",
          "expected_facts": [
            "该用户于今天结束轮岗。",
            "该用户回家后睡了个安稳觉。"
          ],
          "required_groups": [
            ["今天", "今日"],
            ["结束轮岗", "轮岗完毕"],
            ["睡了个安稳觉", "好好睡了一觉"]
          ]
        }
      ]
    }
  ]
}
